                int(
                    _CAPTCHA_TTL_SECONDS
                    - (time.time() - float(row.get("updated_ts") or row.get("created_ts") or time.time()))
                ),
            ),
        }
        if stage == "captcha" and captcha:
            image_type = str(captcha.get("type") or "webp")
