                "success": True,
                "mode": "cookie_reuse" if mode == "manual_captcha" else mode,
                "message": "观影 Cookie 已通过受限搜索验真并复用",
            }

        if has_cookie:
            row["authenticated"] = False
            row["status"] = "login_expired"
            if isinstance(state, dict):
                state.setdefault("nodes", {})[node] = row
